SELECT 'EQUIPMENT' AS kind, capability_id, COALESCE(NULLIF(equipment_id, ''), equipment_class_id, '') AS ref_id, quantity, '' AS uom FROM emc_ops_capability_equipment WHERE COALESCE(NULLIF(TRIM(?), ''), capability_id) = capability_id UNION ALL SELECT 'MATERIAL', capability_id, COALESCE(NULLIF(definition_id, ''), material_class_id, ''), quantity, COALESCE(uom, '') FROM emc_ops_capability_material WHERE COALESCE(NULLIF(TRIM(?), ''), capability_id) = capability_id UNION ALL SELECT 'PERSONNEL', capability_id, COALESCE(NULLIF(person_id, ''), personnel_class_id, ''), quantity, '' FROM emc_ops_capability_personnel WHERE COALESCE(NULLIF(TRIM(?), ''), capability_id) = capability_id UNION ALL SELECT 'SEGMENT', capability_id, segment_id, CAST(1 AS NUMERIC), '' FROM emc_ops_capability_segment WHERE COALESCE(NULLIF(TRIM(?), ''), capability_id) = capability_id
